with parsed as (select id, log_ts, payload_json, context, context['region'] as region, get_json_object(payload_json, '$.user.tier') as user_tier, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, coalesce(context['region'], 'unknown') as region_or_default, coalesce(context['version'], 'direct') as version_or_default from app_logs where log_ts >= '2025-05-01') select date_trunc('day', log_ts) as activity_day, tier, date_trunc('hour', log_ts) as hour_window, count(*) as row_count, count(case when tier = 'free' then 1 end) as free_count, count_if(tier = 'gold') as gold_events, (unix_timestamp(max(log_ts)) - unix_timestamp(min(log_ts))) / 60 as duration_min from parsed group by date_trunc('day', log_ts), tier, date_trunc('hour', log_ts) having free_count >= 1 order by activity_day
